import { useEffect, useState } from "react"
import Link from "next/link"
import { featuredListings, makes } from "@/lib/mock-listings"
import { trackLocalEvent } from "@/lib/analytics-client"
import { useLanguage } from "@/lib/language-client"
import {
  createDemoDraft, reviseDemoDraft, demoAdDraftKey, demoSellerCategories, demoStorageKey,
  initialDemoState, restoreDemoState, submitDemoListing,
  type DemoCondition, type DemoSellerCategory, type NewDemoListing,
} from "@/lib/demo"

type Form = Partial<NewDemoListing>
const fields = "mt-2 w-full rounded-xl border border-border bg-background px-4 py-3 text-sm text-foreground outline-none focus:border-foreground"
const card = "rounded-2xl border border-border bg-card p-5 sm:p-7"
const districts = ["Bagerhat","Bandarban","Barguna","Barishal","Bhola","Bogura","Brahmanbaria","Chandpur","Chapainawabganj","Chattogram","Chuadanga","Cox's Bazar","Cumilla","Dhaka","Dinajpur","Faridpur","Feni","Gaibandha","Gazipur","Gopalganj","Habiganj","Jamalpur","Jashore","Jhalokati","Jhenaidah","Joypurhat","Khagrachhari","Khulna","Kishoreganj","Kurigram","Kushtia","Lakshmipur","Lalmonirhat","Madaripur","Magura","Manikganj","Meherpur","Moulvibazar","Munshiganj","Mymensingh","Naogaon","Narail","Narayanganj","Narsingdi","Natore","Netrokona","Nilphamari","Noakhali","Pabna","Panchagarh","Patuakhali","Pirojpur","Rajbari","Rajshahi","Rangamati","Rangpur","Satkhira","Shariatpur","Sherpur","Sirajganj","Sunamganj","Sylhet","Tangail","Thakurgaon"]
const steps = ["Seller type", "Vehicle identity", "Condition & papers", "Price & location", "Photos & description", "Review & post"]
const bnSteps = ["বিক্রেতার ধরন", "গাড়ির পরিচয়", "অবস্থা ও কাগজপত্র", "দাম ও এলাকা", "ছবি ও বিবরণ", "যাচাই ও পোস্ট"]
const categoryBn: Record<DemoSellerCategory, { label: string; detail: string }> = {
  private: { label: "ব্যক্তিগত বিক্রেতা", detail: "নিজের গাড়ি নিজেই বিক্রি করছি।" },
  reconditioned_dealer: { label: "রিকন্ডিশন্ড ডিলার", detail: "শোরুম থেকে নিবন্ধনবিহীন আমদানি করা গাড়ি বিক্রি করি।" },
  used_car_dealer: { label: "ব্যবহৃত গাড়ির ডিলার", detail: "শোরুম থেকে বাংলাদেশে নিবন্ধিত ব্যবহৃত গাড়ি বিক্রি করি।" },
  brand_new_dealer: { label: "নতুন গাড়ির ডিলার", detail: "শোরুম থেকে ওয়ারেন্টিসহ নতুন গাড়ি বিক্রি করি।" },
}
const initial: Form = { make: "", model: "", grade: "Not listed", year: new Date().getFullYear(), mileageKm: 0,
  engineCc: 1500, fuel: "", transmission: "", body: "", chassisNumber: "", priceBdt: 0, city: "", area: "",
  description: "", photos: [], papersDeclared: false, negotiable: false, features: [], stockStatus: "ready" }

function imageAsWebp(file: File): Promise<string> {
  return new Promise(async (resolve, reject) => {
    if (!["image/jpeg", "image/png", "image/webp"].includes(file.type) || file.size > 15_000_000) {
      reject(new Error("Use JPG, PNG or WebP images under 15 MB each.")); return
    }
    try {
      const bitmap = await createImageBitmap(file)
      let width = Math.min(bitmap.width, 1000), height = Math.round(bitmap.height * width / bitmap.width)
      if (height > 750) { width = Math.round(width * 750 / height); height = 750 }
      const canvas = document.createElement("canvas")
      for (let size = 1000; size >= 400; size -= 150) {
        const ratio = Math.min(1, size / Math.max(width, height))
        canvas.width = Math.max(1, Math.round(width * ratio)); canvas.height = Math.max(1, Math.round(height * ratio))
        canvas.getContext("2d")?.drawImage(bitmap, 0, 0, canvas.width, canvas.height)
        for (const quality of [0.72, 0.58, 0.44, 0.32]) {
          const result = canvas.toDataURL("image/webp", quality)
          if (result.startsWith("data:image/webp;base64,") && result.length <= 105_000) { bitmap.close(); resolve(result); return }
        }
      }
      bitmap.close(); reject(new Error("This image could not be reduced enough. Choose a smaller photo."))
    } catch (error) { reject(error) }
  })
}

function Field({ label, children, hint }: { label: string; children: React.ReactNode; hint?: string }) {
  return <label className="block text-sm font-medium">{label}{children}{hint && <span className="mt-1 block text-xs font-normal text-muted-foreground">{hint}</span>}</label>
}
function money(value: number, bn: boolean) { return `৳${value.toLocaleString(bn ? "bn-BD" : "en-BD")}` }

export function PostAdWizard() {
  const bn = useLanguage() === "bn"
  const [form, setForm] = useState<Form>(initial)
  const [step, setStep] = useState(0)
  const [hydrated, setHydrated] = useState(false)
  const [notice, setNotice] = useState("")
  const [saved, setSaved] = useState("")
  const [busy, setBusy] = useState(false)
  const [postedId, setPostedId] = useState("")
  const [editId, setEditId] = useState("")
  const [lakh, setLakh] = useState("")
  const category = form.sellerCategory
  const dealer = Boolean(category && category !== "private")
  const maxPhotos = dealer ? 30 : 20
  const comparable = featuredListings.filter(item => item.make.toLowerCase() === form.make?.trim().toLowerCase() &&
    item.model.toLowerCase() === form.model?.trim().toLowerCase() && Math.abs(item.year - (form.year || 0)) <= 2 &&
    (!form.city || item.city.toLowerCase() === form.city.trim().toLowerCase())).map(item => item.priceBdt).sort((a,b) => a-b)
  const input = (key: keyof NewDemoListing, value: unknown) => setForm(previous => ({ ...previous, [key]: value }))

  useEffect(() => {
    const timer = window.setTimeout(() => { try {
      const requestedEdit = new URLSearchParams(window.location.search).get("edit")
      if (requestedEdit) {
        const rawListings = localStorage.getItem(demoStorageKey)
        const current = rawListings ? restoreDemoState(JSON.parse(rawListings), featuredListings) : initialDemoState(featuredListings)
        const editable = current.listings.find(item => item.id === requestedEdit && !item.seedSample &&
          (item.status === "draft" || item.status === "rejected"))
        if (editable) {
          setForm({ ...editable, sellerCategory: undefined })
          setEditId(requestedEdit)
          setSaved("Returned ad loaded. Confirm the seller category before editing.")
          setHydrated(true)
          return
        }
      }
      const raw = localStorage.getItem(demoAdDraftKey)
      if (raw) {
        const data = JSON.parse(raw) as { form?: Form; step?: number }
        if (data.form && typeof data.form === "object") {
          setForm({ ...initial, ...data.form, sellerCategory: undefined })
          setStep(0) // Seller type must be chosen on every posting visit, even for a resumed draft.
          setSaved("Draft restored. Confirm who is posting this ad to continue.")
        }
      }
    } catch { /* Start a new browser-only draft. */ }
    setHydrated(true)
    }, 0)
    return () => window.clearTimeout(timer)
  }, [])

  useEffect(() => {
    if (!hydrated || postedId) return
    const timer = window.setTimeout(() => {
      try { localStorage.setItem(demoAdDraftKey, JSON.stringify({ form, step })); setSaved("Draft saved in this browser") }
      catch { setSaved("Browser storage is full. Reduce the number of photos before leaving this page.") }
    }, 600)
    return () => window.clearTimeout(timer)
  }, [form, step, hydrated, postedId])

  const selectCategory = (value: DemoSellerCategory) => {
    const condition: DemoCondition | undefined = value === "reconditioned_dealer" ? "Reconditioned" : value === "used_car_dealer" ? "Used" : value === "brand_new_dealer" ? "Brand new" : undefined
    setForm(previous => ({ ...previous, sellerCategory: value, condition, registrationYear: undefined,
      showroomName: value === "private" ? undefined : previous.showroomName,
      stockNumber: value === "private" ? undefined : previous.stockNumber }))
    setNotice("")
  }

  const verifyStep = (): string | null => {
    if (step === 0 && !category) return "Choose one of the four seller types to continue."
    if (step === 1 && (!form.make?.trim() || !form.model?.trim() || !form.grade?.trim() ||
      !form.year || form.year < 1980 || form.year > new Date().getFullYear() + 1 ||
      !form.engineCc || !form.fuel || !form.transmission || !form.body || !/^[A-HJ-NPR-Z0-9-]{8,25}$/i.test(form.chassisNumber?.trim() || "")))
      return "Complete vehicle identity, specification and chassis/VIN fields."
    if (step === 2 && (!form.condition || form.mileageKm === undefined || form.mileageKm < 0 ||
      form.condition === "Used" && (!form.registrationYear || form.registrationYear < (form.year || 0)) || !form.papersDeclared))
      return "Complete condition, mileage and the original-papers declaration. Used cars need a registration year."
    if (step === 3 && (!form.priceBdt || form.priceBdt < 100_000 || !form.city?.trim() || !form.area?.trim() ||
      dealer && (!form.showroomName?.trim() || !form.stockNumber?.trim() || !form.stockStatus ||
        form.stockStatus === "preorder" && !form.expectedArrival || category === "brand_new_dealer" && !form.warrantyNotes?.trim())))
      return "Complete the asking price and location. Dealer ads also need showroom and stock details."
    if (step === 4 && ((form.photos?.length || 0) < 4 || !form.description || form.description.trim().length < 30))
      return "Add at least four photos and a description of at least 30 characters."
    return null
  }
  const advance = () => {
    const error = verifyStep()
    if (error) { setNotice(error); return }
    setNotice(""); setStep(value => Math.min(value + 1, 5))
    trackLocalEvent("sell_step_completed", { step: steps[step] })
  }

  const addPhotos = async (files: FileList | null, auction = false) => {
    if (!files?.length) return
    if (!auction && (form.photos?.length || 0) + files.length > maxPhotos) { setNotice(`Maximum ${maxPhotos} photos for this seller type.`); return }
    setBusy(true); setNotice("")
    try {
      const converted = await Promise.all(Array.from(files).map(imageAsWebp))
      if (auction) input("auctionSheetPhoto", converted[0])
      else setForm(previous => ({ ...previous, photos: [...(previous.photos || []), ...converted] }))
      setNotice("Photos compressed to WebP and metadata removed in your browser.")
    } catch (error) { setNotice(error instanceof Error ? error.message : "Photo could not be processed.") }
    finally { setBusy(false) }
  }
  const movePhoto = (index: number, offset: number) => {
    const photos = [...(form.photos || [])], target = index + offset
    if (target < 0 || target >= photos.length) return
    ;[photos[index], photos[target]] = [photos[target], photos[index]]
    input("photos", photos)
  }

  const post = () => {
    setNotice("")
    try {
      if (!category) throw new Error("Choose who is posting this ad")
      const actorId = category === "private" ? "demo-private" : "demo-dealer"
      const raw = localStorage.getItem(demoStorageKey)
      const current = raw ? restoreDemoState(JSON.parse(raw), featuredListings) : initialDemoState(featuredListings)
      const ready = { ...form, sellerCategory: category } as NewDemoListing
      const draft = editId ? reviseDemoDraft(current, actorId, editId, ready) : createDemoDraft(current, actorId, ready)
      const id = editId || draft.listings[0].id
      const submitted = submitDemoListing(draft, actorId, id)
      const oldDraft = localStorage.getItem(demoAdDraftKey)
      localStorage.removeItem(demoAdDraftKey)
      try { localStorage.setItem(demoStorageKey, JSON.stringify(submitted)) }
      catch (error) { if (oldDraft) localStorage.setItem(demoAdDraftKey, oldDraft); throw error }
      setPostedId(id)
      trackLocalEvent("sell_step_completed", { step: "submitted", seller_category: category })
    } catch (error) { setNotice(error instanceof Error ? error.message : "The sample ad could not be submitted.") }
  }

  return <main className="flex-1"><div className="mx-auto w-full max-w-6xl px-4 py-10 sm:px-6 lg:py-16">
    <p className="font-mono text-xs uppercase tracking-[0.22em] text-muted-foreground">{bn ? "কারবাই · বিজ্ঞাপন দিন" : "CarBuy · post an ad"}</p>
    <h1 className="mt-3 max-w-3xl text-4xl font-semibold tracking-tight sm:text-6xl">{bn ? "আপনার গাড়ির বিজ্ঞাপন দিন।" : "Put your car in front of buyers."}</h1>
    <p className="mt-4 max-w-3xl text-sm leading-7 text-muted-foreground">{bn ? "প্রথমে আপনার বিক্রেতার ধরন বেছে নিন। তারপর গাড়ির তথ্য, দাম, ছবি ও কাগজপত্রের ঘোষণা দিন। এই প্রিভিউতে কোনো বাস্তব অ্যাকাউন্ট, পেমেন্ট বা যাচাই নেই।" : "First choose how you sell. Then add vehicle details, price, photos and a declaration about original papers. This preview has no real accounts, payments or verification."}</p>
    {postedId ? <section className={`${card} mt-10 max-w-3xl`}><span className="text-3xl">✓</span><h2 className="mt-3 text-3xl font-semibold">{bn ? "বিজ্ঞাপনটি নমুনা পর্যালোচনায় পাঠানো হয়েছে" : "Ad sent to demo review"}</h2><p className="mt-3 text-sm text-muted-foreground">{bn ? "মডারেটর পারসোনা অনুমোদন দিলে এই ব্রাউজারে বিজ্ঞাপনটি দেখা যাবে। এটি আসল প্রকাশনা নয়।" : "Choose the moderator persona in the demo studio to approve it. It becomes visible in this browser only; this is not a real publication."}</p><Link href={`/studio?tab=${dealer ? "dealer" : "sell"}&persona=${dealer ? "demo-dealer" : "demo-private"}`} className="mt-6 inline-block rounded-full bg-foreground px-5 py-3 text-sm font-semibold text-background">{bn ? "আমার বিজ্ঞাপন দেখুন" : "View my demo listings"}</Link></section> : <>
      <nav aria-label="Ad posting steps" className="mt-10 grid grid-cols-3 gap-2 sm:grid-cols-6">{steps.map((name, index) => <button key={name} type="button" onClick={() => { if (index < step) { setStep(index); setNotice("") } }} className={`rounded-xl border px-2 py-3 text-left text-xs ${index === step ? "border-foreground bg-foreground text-background" : index < step ? "border-foreground/50" : "text-muted-foreground"}`} aria-current={index === step ? "step" : undefined}><span className="block font-mono opacity-60">0{index + 1}</span><span className="mt-1 block">{bn ? bnSteps[index] : name}</span></button>)}</nav>
      <div className="mt-8 grid gap-6 lg:grid-cols-[minmax(0,1fr)_280px]"><div className={card}>
        {step === 0 && <><h2 className="text-2xl font-semibold">{bn ? "আপনি কী ধরনের বিক্রেতা?" : "Who is posting this ad?"}</h2><p className="mt-2 text-sm text-muted-foreground">{bn ? "প্রতিবার বিজ্ঞাপন দেওয়ার সময় সঠিক বিভাগ বেছে নিন।" : "Choose the category that describes this sale. We ask for every ad."}</p><div className="mt-6 grid gap-3 sm:grid-cols-2">{demoSellerCategories.map(option => <button key={option.id} type="button" onClick={() => selectCategory(option.id)} aria-pressed={category === option.id} className={`min-h-32 rounded-xl border p-5 text-left transition-colors ${category === option.id ? "border-foreground bg-foreground/10" : "hover:border-foreground/50"}`}><span className="text-lg font-semibold">{bn ? categoryBn[option.id].label : option.label}</span><span className="mt-2 block text-sm text-muted-foreground">{bn ? categoryBn[option.id].detail : option.detail}</span></button>)}</div><p className="mt-5 text-xs text-muted-foreground">{bn ? "ব্যক্তিগত বিক্রেতার সর্বোচ্চ ৩টি সক্রিয় বিজ্ঞাপন; ডিলার ডেমো ক্রেডিট দিয়ে বিজ্ঞাপন জমা দেন।" : "Private sellers can have up to 3 active ads; dealers use sample listing credits in this demo."}</p></>}
        {step === 1 && <><h2 className="text-2xl font-semibold">{bn ? "গাড়ির পরিচয় ও তথ্য" : "Vehicle identity & specification"}</h2><div className="mt-6 grid gap-5 sm:grid-cols-2">
          <Field label={bn ? "মেক *" : "Make *"}><input list="makes" value={form.make || ""} onChange={e => input("make", e.target.value)} className={fields} maxLength={40} placeholder="Toyota" /><datalist id="makes">{makes.map(item => <option key={item} value={item} />)}</datalist></Field>
          <Field label={bn ? "মডেল *" : "Model *"}><input value={form.model || ""} onChange={e => input("model", e.target.value)} className={fields} maxLength={50} placeholder="Axio" /></Field>
          <Field label={bn ? "গ্রেড / ট্রিম *" : "Grade / trim *"} hint={bn ? "গ্রেড জানা না থাকলে Not listed লিখুন" : "Use Not listed when the grade is unknown"}><input value={form.grade || ""} onChange={e => input("grade", e.target.value)} className={fields} maxLength={50} /></Field>
          <Field label={bn ? "মডেল সাল *" : "Model year *"}><input type="number" min={1980} max={new Date().getFullYear()+1} value={form.year || ""} onChange={e => input("year", Number(e.target.value))} className={fields} /></Field>
          <Field label={bn ? "ইঞ্জিন সিসি *" : "Engine cc *"}><input type="number" min={1} max={20000} value={form.engineCc || ""} onChange={e => input("engineCc", Number(e.target.value))} className={fields} /></Field>
          <Field label={bn ? "জ্বালানি *" : "Fuel *"}><select value={form.fuel || ""} onChange={e => input("fuel", e.target.value)} className={fields}><option value="">{bn ? "বেছে নিন" : "Choose fuel"}</option>{["Petrol","Hybrid","Plug-in hybrid","Diesel","CNG","LPG","Electric"].map(v => <option key={v}>{v}</option>)}</select></Field>
          <Field label={bn ? "গিয়ার *" : "Transmission *"}><select value={form.transmission || ""} onChange={e => input("transmission", e.target.value)} className={fields}><option value="">{bn ? "বেছে নিন" : "Choose transmission"}</option>{["Automatic","CVT","Manual","DCT"].map(v => <option key={v}>{v}</option>)}</select></Field>
          <Field label={bn ? "বডি ধরন *" : "Body type *"}><select value={form.body || ""} onChange={e => input("body", e.target.value)} className={fields}><option value="">{bn ? "বেছে নিন" : "Choose body"}</option>{["Sedan","SUV","Crossover","Hatchback","Microbus","Wagon","Pickup","Coupe","Other"].map(v => <option key={v}>{v}</option>)}</select></Field>
          <Field label={bn ? "চ্যাসিস নম্বর / VIN *" : "Chassis number / VIN *"} hint={bn ? "এই নম্বরটি সদৃশ বিজ্ঞাপন শনাক্ত করতে ব্যবহৃত হয়; প্রিভিউতে নমুনা নম্বর ব্যবহার করুন।" : "Used to spot duplicate ads. Enter a sample number in this public preview."}><input value={form.chassisNumber || ""} onChange={e => input("chassisNumber", e.target.value.toUpperCase())} className={fields} maxLength={25} autoComplete="off" placeholder="NZE141-1234567" /></Field>
          <Field label={bn ? "রঙ" : "Colour"}><input value={form.colour || ""} onChange={e => input("colour", e.target.value)} className={fields} maxLength={40} /></Field>
        </div></>}
        {step === 2 && <><h2 className="text-2xl font-semibold">{bn ? "অবস্থা ও কাগজপত্র" : "Condition & paperwork"}</h2><div className="mt-6 grid gap-5 sm:grid-cols-2">
          {category === "private" && <Field label={bn ? "গাড়ির অবস্থা *" : "Car condition *"}><select value={form.condition || ""} onChange={e => setForm(v => ({ ...v, condition: e.target.value as DemoCondition, registrationYear: undefined }))} className={fields}><option value="">{bn ? "বেছে নিন" : "Choose condition"}</option><option>Used</option><option>Reconditioned</option></select></Field>}
          {dealer && <div className="rounded-xl border p-4 text-sm"><span className="text-muted-foreground">{bn ? "বিভাগ অনুযায়ী অবস্থা" : "Condition from seller category"}</span><strong className="mt-1 block">{form.condition}</strong></div>}
          <Field label={bn ? "চালানো কিলোমিটার *" : "Mileage in km *"}><input type="number" min={0} max={1000000} value={form.mileageKm ?? ""} onChange={e => input("mileageKm", Number(e.target.value))} className={fields} /></Field>
          {form.condition === "Used" && <><Field label={bn ? "বাংলাদেশে নিবন্ধনের সাল *" : "Bangladesh registration year *"}><input type="number" min={form.year || 1980} max={new Date().getFullYear()+1} value={form.registrationYear || ""} onChange={e => input("registrationYear", Number(e.target.value))} className={fields} /></Field><Field label={bn ? "নিবন্ধন নম্বর (ঐচ্ছিক)" : "Registration number (optional)"}><input value={form.registrationNumber || ""} onChange={e => input("registrationNumber", e.target.value)} className={fields} maxLength={40} placeholder="Dhaka Metro…" /></Field><Field label={bn ? "আগের মালিকের সংখ্যা" : "Number of owners"}><input type="number" min={1} max={20} value={form.owners || ""} onChange={e => input("owners", e.target.value ? Number(e.target.value) : undefined)} className={fields} /></Field><Field label={bn ? "ট্যাক্স টোকেন মেয়াদ" : "Tax token expiry"}><input type="date" value={form.taxTokenExpiry || ""} onChange={e => input("taxTokenExpiry", e.target.value)} className={fields} /></Field><Field label={bn ? "ফিটনেস মেয়াদ" : "Fitness expiry"}><input type="date" value={form.fitnessExpiry || ""} onChange={e => input("fitnessExpiry", e.target.value)} className={fields} /></Field></>}
          {form.condition === "Reconditioned" && <><Field label={bn ? "অকশন গ্রেড" : "Auction grade"}><input value={form.auctionGrade || ""} onChange={e => input("auctionGrade", e.target.value)} className={fields} maxLength={20} placeholder="4.5" /></Field><Field label={bn ? "অকশন শিটের নমুনা ছবি" : "Sample auction sheet image"} hint={bn ? "বিক্রেতার দেওয়া; কারবাই যাচাই করেনি। আসল ব্যক্তিগত নথি আপলোড করবেন না।" : "Seller supplied and unverified. Do not upload a real private document here."}><input type="file" accept="image/jpeg,image/png,image/webp" onChange={e => void addPhotos(e.target.files, true)} className={fields} />{form.auctionSheetPhoto && <span className="mt-2 block text-xs">{bn ? "নমুনা ছবি যোগ হয়েছে" : "Sample image added"}</span>}</Field></>}
        </div><label className="mt-7 flex items-start gap-3 rounded-xl border p-4 text-sm"><input type="checkbox" checked={Boolean(form.papersDeclared)} onChange={e => input("papersDeclared", e.target.checked)} className="mt-1" /><span>{bn ? "আমি নিশ্চিত করছি যে গাড়ির তথ্য সঠিক এবং ক্রেতাকে আসল কাগজপত্র দেখাতে পারব। এটি বিক্রেতার ঘোষণা, কারবাইয়ের যাচাই নয়। *" : "I confirm these vehicle details are accurate and I can show original papers to a buyer. This is my declaration, not a CarBuy verification. *"}</span></label><p className="mt-3 text-xs text-muted-foreground">{bn ? "এই পাবলিক প্রিভিউতে জাতীয় পরিচয়পত্র, BRTA নথি বা মালিকানার দলিল আপলোড করবেন না।" : "Do not upload NID, BRTA documents or ownership records into this public browser preview."}</p></>}
        {step === 3 && <><h2 className="text-2xl font-semibold">{bn ? "দাম ও অবস্থান" : "Asking price & location"}</h2><div className="mt-6 grid gap-5 sm:grid-cols-2"><Field label={bn ? "দাম (টাকা) *" : "Asking price (BDT) *"}><input type="number" min={100000} max={100000000} step={1000} value={form.priceBdt || ""} onChange={e => { input("priceBdt", Number(e.target.value)); setLakh("") }} className={fields} /></Field><Field label={bn ? "লাখ হিসেবে দ্রুত লিখুন" : "Quick price in lakh"} hint={bn ? "যেমন 28.5 লাখ = ৳28,50,000" : "For example, 28.5 lakh = ৳28,50,000"}><input type="number" min={1} max={1000} step={0.01} value={lakh} onChange={e => { setLakh(e.target.value); input("priceBdt", Math.round(Number(e.target.value) * 100000)) }} className={fields} placeholder="28.5" /></Field><Field label={bn ? "জেলা *" : "District *"}><input list="districts" value={form.city || ""} onChange={e => input("city", e.target.value)} className={fields} placeholder="Dhaka" /><datalist id="districts">{districts.map(v => <option key={v} value={v} />)}</datalist></Field><Field label={bn ? "এলাকা *" : "Area *"}><input value={form.area || ""} onChange={e => input("area", e.target.value)} className={fields} maxLength={60} placeholder="Uttara" /></Field></div><div className="mt-5 rounded-xl border p-4 text-sm text-muted-foreground">{comparable.length >= 5 ? (bn ? `একই মডেল, কাছাকাছি সাল ও জেলার ${comparable.length}টি নমুনা চাওয়া দামের মাঝামাঝি মূল্য ${money(comparable[Math.floor(comparable.length/2)], true)}। এটি বিক্রয়মূল্য বা মূল্যায়ন নয়।` : `${comparable.length} comparable sample asking prices: median ${money(comparable[Math.floor(comparable.length/2)], false)}. This is not a sale price or valuation.`) : (bn ? "মূল্য পরামর্শ দেখাতে একই মডেল, কাছাকাছি সাল ও জেলার অন্তত ৫টি নমুনা বিজ্ঞাপন দরকার।" : "Price guidance needs at least 5 sample ads for the same model, nearby year and district.")}</div><label className="mt-5 flex items-center gap-3 text-sm"><input type="checkbox" checked={Boolean(form.negotiable)} onChange={e => input("negotiable", e.target.checked)} />{bn ? "দাম আলোচনা সাপেক্ষ" : "Price is negotiable"}</label>
          {dealer && <div className="mt-8 border-t pt-7"><h3 className="text-lg font-semibold">{bn ? "শোরুমের স্টক তথ্য" : "Showroom stock details"}</h3><div className="mt-5 grid gap-5 sm:grid-cols-2"><Field label={bn ? "শোরুমের নাম *" : "Showroom name *"}><input value={form.showroomName || ""} onChange={e => input("showroomName", e.target.value)} className={fields} maxLength={80} /></Field><Field label={bn ? "স্বতন্ত্র স্টক নম্বর *" : "Unique stock number *"}><input value={form.stockNumber || ""} onChange={e => input("stockNumber", e.target.value)} className={fields} maxLength={32} placeholder="CB-001" /></Field><Field label={bn ? "স্টকের অবস্থা *" : "Stock status *"}><select value={form.stockStatus || ""} onChange={e => input("stockStatus", e.target.value)} className={fields}><option value="ready">Ready</option><option value="preorder">Pre-order</option></select></Field>{form.stockStatus === "preorder" && <Field label={bn ? "আসার সম্ভাব্য তারিখ *" : "Expected arrival *"}><input type="date" value={form.expectedArrival || ""} onChange={e => input("expectedArrival", e.target.value)} className={fields} /></Field>}<Field label={bn ? "বিক্রয়োত্তর সেবা" : "After-sales support"}><input value={form.afterSalesNotes || ""} onChange={e => input("afterSalesNotes", e.target.value)} className={fields} maxLength={300} /></Field>{category === "brand_new_dealer" && <Field label={bn ? "ওয়ারেন্টির শর্ত *" : "Warranty terms *"}><input value={form.warrantyNotes || ""} onChange={e => input("warrantyNotes", e.target.value)} className={fields} maxLength={300} placeholder="3 years or 100,000 km…" /></Field>}</div></div>}
        </>}
        {step === 4 && <><h2 className="text-2xl font-semibold">{bn ? "ছবি ও বিবরণ" : "Photos & description"}</h2><p className="mt-2 text-sm text-muted-foreground">{bn ? `কমপক্ষে ৪টি, সর্বোচ্চ ${maxPhotos}টি ছবি। সামনে, পেছনে, দুই পাশ, ভেতর এবং ত্রুটি দেখান।` : `Add 4–${maxPhotos} photos. Show front, rear, sides, interior and any damage.`}</p><input type="file" accept="image/jpeg,image/png,image/webp" multiple onChange={e => { void addPhotos(e.target.files); e.target.value = "" }} className={`${fields} mt-5`} disabled={busy} /><p className="mt-2 text-xs text-muted-foreground">{bn ? "ছবি ছোট WebP-তে রূপান্তর করে অবস্থানের মেটাডেটা বাদ দেওয়া হয়। সব তথ্য এই ব্রাউজারে থাকে।" : "Photos are compressed to WebP and location metadata is removed. Everything stays in this browser."}</p><div className="mt-5 grid grid-cols-2 gap-3 sm:grid-cols-4">{form.photos?.map((photo, index) => <div key={`${index}-${photo.slice(-12)}`} className="overflow-hidden rounded-xl border"><img src={photo} alt={`Vehicle photo ${index+1}`} className="aspect-[4/3] w-full object-cover" /><div className="flex justify-between gap-1 p-2 text-xs"><button type="button" onClick={() => movePhoto(index,-1)} disabled={index===0} aria-label={`Move photo ${index+1} left`}>←</button><span>{index+1}</span><button type="button" onClick={() => movePhoto(index,1)} disabled={index===(form.photos?.length||0)-1} aria-label={`Move photo ${index+1} right`}>→</button><button type="button" onClick={() => input("photos", form.photos?.filter((_,i)=>i!==index))} aria-label={`Remove photo ${index+1}`}>×</button></div></div>)}</div><p className="mt-3 text-sm text-muted-foreground">{form.photos?.length || 0} / {maxPhotos}</p><button type="button" onClick={() => input("description", bn ? `${form.year} ${form.make} ${form.model} ${form.grade}। ${form.condition} গাড়ি, চলেছে ${form.mileageKm} কিমি। অবস্থান: ${form.area}, ${form.city}। কন্ডিশন, সার্ভিস ইতিহাস এবং পরিচিত ত্রুটি এখানে বিস্তারিত লিখুন।` : `${form.year} ${form.make} ${form.model} ${form.grade}. ${form.condition} car with ${form.mileageKm} km. Located in ${form.area}, ${form.city}. Add your actual condition, service history and known faults here.`)} className="mb-4 rounded-full border px-4 py-2 text-xs">{bn ? "সম্পাদনাযোগ্য বিবরণের নমুনা তৈরি করুন" : "Create editable description template"}</button><Field label={bn ? "গাড়ির বিবরণ (কমপক্ষে ৩০ অক্ষর) *" : "Vehicle description (at least 30 characters) *"} hint={bn ? "অবস্থা, সার্ভিস ইতিহাস, বৈশিষ্ট্য ও পরিচিত ত্রুটি লিখুন। বাংলা বা ইংরেজি ব্যবহার করুন। ফোন নম্বর বা লিংক দেবেন না।" : "Describe condition, service history, features and known faults. Bangla or English is welcome. No phone numbers or links."}><textarea value={form.description || ""} onChange={e => input("description", e.target.value)} maxLength={2000} className={`${fields} min-h-40`} /></Field><Field label={bn ? "বৈশিষ্ট্য (কমা দিয়ে আলাদা করুন)" : "Features (separate with commas)"}><input value={form.features?.join(", ") || ""} onChange={e => input("features", e.target.value.split(",").map(v=>v.trim()).filter(Boolean).slice(0,20))} className={fields} placeholder="ABS, Camera, Cruise control" /></Field></>}
        {step === 5 && <><h2 className="text-2xl font-semibold">{bn ? "বিজ্ঞাপন দেখে জমা দিন" : "Review your ad"}</h2><p className="mt-2 text-sm text-muted-foreground">{bn ? "জমা দিলে বিজ্ঞাপনটি নমুনা মডারেশন তালিকায় যাবে।" : "Submitting sends the ad to the sample moderation queue."}</p><div className="mt-6 grid gap-4 sm:grid-cols-2"><div><span className="text-xs text-muted-foreground">{bn ? "বিক্রেতা" : "Seller"}</span><strong className="mt-1 block">{category ? bn ? categoryBn[category].label : demoSellerCategories.find(v=>v.id===category)?.label : "—"}</strong></div><div><span className="text-xs text-muted-foreground">{bn ? "গাড়ি" : "Vehicle"}</span><strong className="mt-1 block" translate="no">{form.year} {form.make} {form.model} {form.grade}</strong></div><div><span className="text-xs text-muted-foreground">{bn ? "অবস্থা" : "Condition"}</span><strong className="mt-1 block">{form.condition}</strong></div><div><span className="text-xs text-muted-foreground">{bn ? "দাম" : "Price"}</span><strong className="mt-1 block">{money(form.priceBdt || 0,bn)} {form.negotiable ? bn ? "· আলোচনা সাপেক্ষ" : "· negotiable" : ""}</strong></div><div><span className="text-xs text-muted-foreground">{bn ? "অবস্থান" : "Location"}</span><strong className="mt-1 block" translate="no">{form.area}, {form.city}</strong></div><div><span className="text-xs text-muted-foreground">{bn ? "ছবি" : "Photos"}</span><strong className="mt-1 block">{form.photos?.length || 0}</strong></div></div><p className="mt-6 rounded-xl border p-4 text-sm leading-7" translate="no">{form.description}</p><div className="mt-5 rounded-xl border border-amber-500/40 bg-amber-500/5 p-4 text-xs leading-6 text-muted-foreground">{bn ? "এটি ব্রাউজারভিত্তিক ডেমো। আসল পরিচয় যাচাই, গাড়ি যাচাই, বিজ্ঞাপন ফি বা ক্রেতাকে বিজ্ঞাপন প্রকাশ করা হয় না।" : "This is a browser-only demo. No real identity verification, vehicle checks, listing fee or public buyer publication occurs."}</div><button type="button" onClick={post} className="mt-6 rounded-full bg-foreground px-6 py-3 text-sm font-semibold text-background">{bn ? "নমুনা পর্যালোচনায় জমা দিন" : "Submit for demo review"}</button></>}
        {notice && <p role="alert" className="mt-6 rounded-xl border border-amber-500/50 p-4 text-sm text-amber-300">{notice}</p>}
        <div className="mt-8 flex items-center justify-between border-t pt-6"><button type="button" onClick={() => { setStep(v => Math.max(0,v-1)); setNotice("") }} disabled={step===0} className="rounded-full border px-5 py-3 text-sm disabled:opacity-30">{bn ? "পেছনে" : "Back"}</button>{step < 5 && <button type="button" onClick={advance} disabled={busy} className="rounded-full bg-foreground px-6 py-3 text-sm font-semibold text-background disabled:opacity-50">{bn ? "পরবর্তী ধাপ" : "Continue"} →</button>}</div>
      </div><aside className="space-y-4"><div className={card}><h3 className="font-semibold">{bn ? "প্রিভিউতে কী আছে" : "Included in this preview"}</h3><ul className="mt-4 space-y-3 text-sm text-muted-foreground"><li>✓ {bn ? "চার ধরনের বিক্রেতা" : "Four seller categories"}</li><li>✓ {bn ? "বাংলাদেশি দাম ও জেলা" : "Bangladesh pricing & districts"}</li><li>✓ {bn ? "ছবি সাজানো ও ছোট করা" : "Photo ordering & compression"}</li><li>✓ {bn ? "ব্রাউজারে খসড়া সংরক্ষণ" : "Browser draft autosave"}</li><li>✓ {bn ? "ডেমো মডারেশন" : "Demo moderation"}</li></ul></div><div className={card}><h3 className="font-semibold">{bn ? "খরচ ও মেয়াদ" : "Cost & duration"}</h3><p className="mt-3 text-sm leading-6 text-muted-foreground">{bn ? "ডেমোতে কোনো টাকা নেওয়া হয় না। PRD অনুযায়ী ব্যক্তিগত বিজ্ঞাপনের লক্ষ্য ৬০ দিন, ডিলারের ৩০ দিন; আসল ফি প্রকাশের আগে নির্ধারিত হবে।" : "No money is collected in the demo. The PRD targets 60 days for private ads and 30 for dealer ads; real fees must be set before launch."}</p></div><p className="text-xs text-muted-foreground" role="status">{saved}</p></aside></div>
    </>}
  </div></main>
}
